# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# SD4-form loads and stores (VLEPEM Rev. 0 Figure A-8).  SD4 is scaled by
# the access size.

# CHECK: se_lbz 3, 0(4) # encoding: [0x80,0x34]
se_lbz 3, 0(4)
# CHECK: se_lbz 3, 15(4) # encoding: [0x8f,0x34]
se_lbz 3, 15(4)
# CHECK: se_lhz 3, 30(4) # encoding: [0xaf,0x34]
se_lhz 3, 30(4)
# CHECK: se_lwz 3, 60(4) # encoding: [0xcf,0x34]
se_lwz 3, 60(4)
# CHECK: se_lwz 24, 4(31) # encoding: [0xc1,0x8f]
se_lwz 24, 4(31)
# CHECK: se_stb 3, 15(4) # encoding: [0x9f,0x34]
se_stb 3, 15(4)
# CHECK: se_sth 3, 2(4) # encoding: [0xb1,0x34]
se_sth 3, 2(4)
# CHECK: se_stw 31, 4(24) # encoding: [0xd1,0xf8]
se_stw 31, 4(24)
